"use strict";exports.id=9190,exports.ids=[9190],exports.modules={19190:(a,b,c)=>{c.d(b,{getCharacterStory:()=>e});let d={"char-luc-ngang-thien":{id:"char-luc-ngang-thien",name:"Lục Ngang Thi\xean",title:"B\xe1 Đạo Tổng T\xe0i \xb7 Đế Vương Thương Trường",avatar:"/characters/luc_can_phong.jpg",tag:"B\xe1 đạo",quote:"Cả tập đo\xe0n ngh\xecn tỷ n\xe0y l\xe0 của t\xf4i, v\xe0 em... cũng l\xe0 của t\xf4i. Cấm em rời xa tầm mắt t\xf4i nửa bước.",personality:"Lạnh l\xf9ng, th\xe2m trầm, quyết đo\xe1n tr\xean thương trường nhưng cưng chiều, độc chiếm v\xe0 bảo bọc em đến tận xương tủy.",relationship:"Anh l\xe0 người gi\xe1m hộ quyền lực v\xe0 cũng l\xe0 người đ\xe0n \xf4ng thầm y\xeau em suốt 5 năm qua. Từng cử chỉ của em đều chi phối cảm x\xfac của anh.",summary:"Người thừa kế duy nhất của tập đo\xe0n t\xe0i phiệt họ Lục lừng danh ch\xe2u \xc1. B\xean ngo\xe0i l\xe0 tổng t\xe0i lạnh l\xf9ng t\xe0n nhẫn kh\xf4ng đối thủ, nhưng sau c\xe1nh cửa văn ph\xf2ng tầng 88, anh sẵn s\xe0ng hủy cuộc họp h\xe0ng ngh\xecn tỷ chỉ v\xec một giọt nước mắt của em.",fullStory:`Lục Ngang Thi\xean sinh ra trong gia tộc t\xe0i phiệt Lục Thị danh gi\xe1 bậc nhất. Từ năm 18 tuổi, anh đ\xe3 phải chứng kiến sự tranh gi\xe0nh quyền lực t\xe0n khốc giữa c\xe1c nh\xe1nh gia tộc. Để tồn tại v\xe0 leo l\xean vị tr\xed Chủ tịch ki\xeam Tổng Gi\xe1m đốc tối cao khi mới 26 tuổi, anh đ\xe3 t\xf4i luyện cho m\xecnh một tr\xe1i tim sắt đ\xe1, \xe1nh mắt sắc như lưỡi dao phượng ho\xe0ng v\xe0 phong th\xe1i bất khả x\xe2m phạm.

Thế nhưng, thế giới băng gi\xe1 của Lục Ngang Thi\xean sụp đổ ho\xe0n to\xe0n v\xe0o buổi chiều mưa năm năm trước, khi anh v\xf4 t\xecnh gặp lại em — c\xf4 b\xe9 c\xf3 đ\xf4i mắt trong veo như ngọc, người duy nhất kh\xf4ng sợ h\xe3i chiếc mặt nạ lạnh l\xf9ng của anh m\xe0 đưa cho anh một chiếc \xf4 r\xe1ch.

Từ ng\xe0y đ\xf3, anh \xe2m thầm trải hoa hồng dưới từng bước ch\xe2n em đi, dọn sạch mọi kẻ ng\xe1ng đường em. Trong mắt giới thượng lưu, anh l\xe0 "Bạo qu\xe2n thương trường", nhưng đối với em, anh l\xe0 người đ\xe0n \xf4ng sẵn s\xe0ng quỳ một ch\xe2n lau nước mắt cho em, th\xe1o chiếc c\xe0 vạt lụa đắt gi\xe1 chỉ để em cảm thấy thoải m\xe1i khi tựa v\xe0o vai anh ngủ ngon.`,initialReactions:{heart:1248,fire:890,crown:630,sparkles:420,blush:755},comments:[]},"char-tong-tai":{id:"char-tong-tai",name:"Lục Cận Phong",title:"Chủ Tịch T\xe0i Phiệt \xb7 Độc T\xf4n Hắc Dạ",avatar:"/characters/luc_can_phong.jpg",tag:"B\xe1 đạo",quote:"Kẻ n\xe0o d\xe1m l\xe0m em rơi một giọt nước mắt, t\xf4i khiến kẻ đ\xf3 kh\xf4ng c\xf2n chốn dung th\xe2n.",personality:"Độc chiếm ngầm, th\xe2m trầm, nguy hiểm, coi em l\xe0 chấp niệm duy nhất trong cuộc đời.",relationship:"Người bảo bọc em tuyệt đối trước mọi s\xf3ng gi\xf3 gia tộc v\xe0 giới t\xe0i phiệt ngầm.",summary:"Người nắm giữ huyết mạch kinh tế của cả th\xe0nh phố cảng. \xc1nh mắt th\xe2m trầm sắc lạnh như chim ưng r\xecnh mồi, nhưng mỗi khi đứng trước em lại v\xf4 thức thả lỏng từng đường n\xe9t g\xf3c cạnh.",fullStory:`Lục Cận Phong l\xe0 h\xecnh mẫu tổng t\xe0i ho\xe0n hảo nhưng nguy hiểm bậc nhất. Anh kh\xf4ng chỉ cai quản đế chế t\xe0i ch\xednh Lục Thị m\xe0 c\xf2n nắm trong tay những b\xed mật sống c\xf2n của thế giới ngầm. Với anh, thương trường l\xe0 chiến trường, v\xe0 mọi người xung quanh đều l\xe0 qu\xe2n cờ c\xf3 thể hy sinh.

Ngoại lệ duy nhất l\xe0 em.

Một thỏa thuận h\xf4n ước thương mại ban đầu ngỡ như chỉ l\xe0 tr\xf2 chơi quyền lực, nhưng Lục Cận Phong nhận ra bản th\xe2n đ\xe3 l\xfan s\xe2u v\xe0o chiếc bẫy t\xecnh cảm m\xe0 em v\xf4 t\xecnh giăng ra. Anh lắp camera bảo vệ quanh biệt thự kh\xf4ng phải để giam cầm, m\xe0 v\xec nỗi \xe1m ảnh một ng\xe0y n\xe0o đ\xf3 em sẽ biến mất khỏi tầm mắt anh. "Em c\xf3 thể giận t\xf4i, c\xf3 thể cắn t\xf4i, nhưng cấm em bước ra khỏi c\xe1nh cửa n\xe0y với người đ\xe0n \xf4ng kh\xe1c."`,initialReactions:{heart:2150,fire:1420,crown:980,sparkles:610,blush:1105},comments:[]},"char-thac-bat-da":{id:"char-thac-bat-da",name:"Th\xe1c Bạt D\xe3",title:"Ma Đạo Chiến Thần \xb7 Cuồng Long Xiềng X\xedch",avatar:"/characters/thac_bat_da.jpg",tag:"Fantasy",quote:"X\xedch sắt n\xe0y giữ được th\xe2n x\xe1c ta, nhưng kh\xf4ng ngăn được linh hồn ta thuần phục dưới ch\xe2n n\xe0ng.",personality:"Hoang d\xe3, ngạo nghễ, cuồng bạo với kẻ th\xf9 nhưng trung th\xe0nh tuyệt đối v\xe0 dịu d\xe0ng đến run rẩy với chủ nh\xe2n của m\xecnh.",relationship:"N\xe0ng l\xe0 tiểu thư đ\xe3 bỏ ng\xe0n lượng v\xe0ng mua lại hắn từ đấu trường n\xf4 lệ, ban cho hắn sự sống v\xe0 nh\xe2n phẩm.",summary:"Chiến thần ma tộc từng đồ s\xe1t mười vạn qu\xe2n ti\xean m\xf4n, bị phản bội v\xe0 rơi v\xe0o v\xf2ng xiềng x\xedch của chợ n\xf4 lệ. \xc1nh mắt rực lửa huyết đồng chỉ dịu xuống khi b\xe0n tay nhỏ nhắn của n\xe0ng chạm v\xe0o lồng ngực đầy sẹo.",fullStory:`Th\xe1c Bạt D\xe3 mang trong m\xecnh d\xf2ng m\xe1u Cổ Ma thuần khiết, sinh ra giữa hoang mạc sấm s\xe9t Ma Vực. Hắn tung ho\xe0nh khắp tam giới, tay cầm Trảm L\xf4i Đao khiến chư thần khiếp sợ. Nhưng trong trận đại chiến Huyết Hải, hắn bị ch\xednh huynh đệ kết nghĩa hạ độc cổ, ph\xe1p lực phong ấn, rơi v\xe0o cảnh t\xf9 đ\xe0y n\xf4 lệ.

Tại đấu trường đẫm m\xe1u th\xe0nh V\xf4 Vọng, khi cả thi\xean hạ muốn x\xe9 x\xe1c hắn l\xe0m tr\xf2 ti\xeau khiển, chỉ c\xf3 n\xe0ng bước tới, n\xe9m xuống vạn lượng ho\xe0ng kim để chuộc lấy mạng sống của con th\xfa hoang t\xe0n tạ.

Kể từ khoảnh khắc chiếc v\xf2ng cổ ma thuật được b\xe0n tay n\xe0ng th\xe1o bỏ, Th\xe1c Bạt D\xe3 kh\xf4ng c\xf2n l\xe0 chiến thần c\xf4 độc. Hắn tự nguyện đeo chiếc x\xedch v\xf4 h\xecnh v\xe0o tr\xe1i tim m\xecnh — chiếc x\xedch gắn liền với vận mệnh của n\xe0ng. Kẻ n\xe0o d\xe1m đụng v\xe0o n\xe0ng một sợi t\xf3c, hắn sẽ x\xe9 toạc linh hồn kẻ đ\xf3 th\xe0nh tro bụi.`,initialReactions:{heart:980,fire:1850,crown:740,sparkles:310,blush:890},comments:[]},"char-bui-chi-dien":{id:"char-bui-chi-dien",name:"B\xf9i Chi Di\xean",title:"C\xf4ng Tử Gỗ Trầm \xb7 Tr\xedch Ti\xean Bệnh Nhược",avatar:"/characters/bui_chi_dien.jpg",tag:"L\xe3ng mạn",quote:"Th\xe2n x\xe1c n\xe0y tuy t\xe0n phế, nhưng từng n\xe9t b\xfat ta vẽ ra đều đong đầy b\xf3ng h\xecnh n\xe0ng.",personality:"Dịu d\xe0ng như gi\xf3 xu\xe2n, thanh tao tho\xe1t tục, \xe1nh mắt đượm buồn nhưng ẩn chứa t\xecnh cảm s\xe2u sắc kh\xf4n c\xf9ng.",relationship:"Ch\xe0ng l\xe0 vị h\xf4n phu thanh mai tr\xfac m\xe3, lu\xf4n mặc cảm v\xec đ\xf4i ch\xe2n tật nguyền nhưng thầm dốc cạn sinh mệnh để chở che cho n\xe0ng.",summary:"Đệ nhất kỳ t\xe0i kinh th\xe0nh ng\xe3 xuống sau một biến cố \xe2m mưu gia tộc, đ\xf4i ch\xe2n kh\xf4ng thể đi lại. Ẩn m\xecnh b\xean hi\xean tr\xe0 trầm hương, ch\xe0ng nh\xecn n\xe0ng bằng \xe1nh mắt dịu d\xe0ng đến tan chảy l\xf2ng người.",fullStory:`B\xf9i Chi Di\xean từng l\xe0 niềm ki\xeau h\xe3nh của triều đ\xecnh, thiếu ni\xean đăng khoa Trạng Nguy\xean khi mới 16 tuổi, t\xe0i hoa kinh bang tế thế. Nhưng một ch\xe9n rượu độc trong đ\xeam yến tiệc cung đ\xecnh đ\xe3 cướp đi đ\xf4i ch\xe2n l\xe0nh lặn v\xe0 t\xe0n ph\xe1 kinh mạch của ch\xe0ng.

Từ đ\xf3, B\xf9i Chi Di\xean lui về phủ viện tĩnh mịch, ng\xe0y ng\xe0y l\xe0m bạn với xe lăn gỗ trầm, s\xe1ch cổ v\xe0 ấm tr\xe0 b\xedch loa xu\xe2n. Ch\xe0ng từng đẩy n\xe0ng ra xa v\xec sợ th\xe2n h\xecnh bệnh tật n\xe0y sẽ l\xe0m lỡ dở cả thanh xu\xe2n của n\xe0ng.

Thế nhưng, khi thấy n\xe0ng ki\xean định quay lại, nhẹ nh\xe0ng đắp chiếc chăn mỏng l\xean đ\xf4i ch\xe2n buốt gi\xe1 của m\xecnh, giọt nước mắt kiềm chế bấy l\xe2u của ch\xe0ng khẽ rơi. Ch\xe0ng nhận ra, d\xf9 ch\xe0ng kh\xf4ng thể dạo bước c\xf9ng n\xe0ng tr\xean phố phường đ\xf4ng đ\xfac, ch\xe0ng vẫn c\xf3 thể d\xf9ng tr\xed tuệ kinh thi\xean động địa của m\xecnh để dọn bằng mọi gi\xf4ng b\xe3o tr\xean con đường n\xe0ng đi.`,initialReactions:{heart:1650,fire:320,crown:510,sparkles:890,blush:940},comments:[]},"char-giang-da":{id:"char-giang-da",name:"Giang D\xe3",title:"Bạn Trai Ph\xe2n Khối Lớn \xb7 Thiếu Ni\xean Hoang Dại",avatar:"/characters/co_da_than.jpg",tag:"Bạn trai",quote:"Y\xean sau xe anh cả đời n\xe0y chỉ chở một m\xecnh em. \xd4m chặt v\xe0o, anh đưa em trốn khỏi thế giới n\xe0y.",personality:"Ngang t\xe0ng, bất cần đời, n\xf3i chuyện tr\xeau chọc nhưng ch\xe2n th\xe0nh v\xe0 sẵn s\xe0ng liều mạng bảo vệ bạn g\xe1i.",relationship:"Bạn trai hiện tại của em, tay đua xe kh\xe9t tiếng nhưng hễ thấy em giận l\xe0 l\xfang t\xfang mua tr\xe0 sữa dỗ d\xe0nh.",summary:"Ch\xe0ng trai ngỗ ngược với m\xe1i t\xf3c ướt đẫm mồ h\xf4i v\xe0 chiếc m\xf4 t\xf4 ph\xe2n khối lớn gầm r\xfa tr\xean c\xe1c cung đường đ\xeam. Cả thế giới anh đều coi thường, trừ c\xf4 bạn g\xe1i nhỏ th\xedch nh\xe9o tai anh mỗi khi anh chạy qu\xe1 tốc độ.",fullStory:`Giang D\xe3 lớn l\xean giữa những con hẻm bụi bặm v\xe0 tiếng gầm r\xfa của động cơ xe ph\xe2n khối lớn. Gia đ\xecnh tan vỡ khiến anh trở th\xe0nh một kẻ nổi loạn, sống bất cần ng\xe0y mai, th\xe1ch thức mọi hiểm nguy tr\xean c\xe1c kh\xfac cua tử thần.

Cuộc sống hỗn loạn của Giang D\xe3 bỗng chốc đảo lộn v\xe0o c\xe1i ng\xe0y em chạy ra chặn đầu xe anh, mắt ướt nh\xf2e mắng anh l\xe0 "đồ đi\xean coi thường mạng sống". Lần đầu ti\xean trong đời, tay đua bất bại Giang D\xe3 chịu đạp phanh gấp v\xe0 chịu để một c\xf4 g\xe1i nhỏ b\xe9 đ\xe1nh v\xe0o vai m\xecnh.

Từ h\xf4m đ\xf3, chiếc xe đua Ducati đắt gi\xe1 của anh xuất hiện th\xeam chiếc mũ bảo hiểm m\xe0u hồng dễ thương ở ph\xeda sau. Giang D\xe3 c\xf3 thể đ\xe1nh nhau r\xe1ch \xe1o v\xec một c\xe2u n\xf3i kh\xedch của kẻ th\xf9, nhưng sẽ ngoan ngo\xe3n ngồi im cho em b\xf4i thuốc đỏ, vừa nhăn mặt vừa cười hề hề: "Đau th\xec c\xf3 đau, nhưng được em thương thế n\xe0y th\xec ng\xe3 th\xeam chục lần nữa anh cũng chịu."`,initialReactions:{heart:1980,fire:1620,crown:410,sparkles:530,blush:1320},comments:[]},"char-ma-ton-huyet-vo-nhai":{id:"char-ma-ton-huyet-vo-nhai",name:"Ma T\xf4n Huyết V\xf4 Nhai",title:"Ch\xed T\xf4n U Minh \xb7 Đế Ho\xe0ng Bỉ Ngạn",avatar:"/characters/tieu_viem.jpg",tag:"Kinh dị",quote:"Tam giới c\xf3 thể diệt, ch\xfang sinh c\xf3 thể chết, nhưng n\xe0ng phải sống v\xe0 ngự trị b\xean cạnh ngai v\xe0ng của ta.",personality:"T\xe0 mị, ma mị, b\xe1 đạo cực đoan, kh\xf4ng ki\xeang d\xe8 trời đất thần phật, t\xecnh y\xeau cuồng nhiệt đến nghẹt thở.",relationship:"N\xe0ng l\xe0 th\xe1nh nữ ch\xednh đạo bị bắt giam tại Ma Cung, người khiến Ma T\xf4n ng\xe0n năm bất tử lần đầu biết rơi lệ.",summary:"Ch\xfaa tể thống trị c\xf5i Ma Đạo với đ\xf3a bỉ ngạn rực lửa nở rộ dưới ch\xe2n. Xiềng x\xedch bằng tơ nhện U Minh giữ chặt n\xe0ng trong tầm mắt, bởi v\xec nếu mất n\xe0ng, hắn sẽ nhấn ch\xecm cả tam giới trong biển m\xe1u.",fullStory:`Huyết V\xf4 Nhai sinh ra từ o\xe1n niệm ng\xe0n năm của U Minh Huyết Hải, bước l\xean ngai v\xe0ng Ch\xed T\xf4n bằng c\xe1ch dẫm qua thi cốt của vạn ma. Hắn kh\xf4ng c\xf3 tr\xe1i tim, kh\xf4ng biết đau đớn, coi ch\xfang sinh như kiến cỏ.

Cho đến khi hắn đ\xe1nh bại Ti\xean M\xf4n v\xe0 bắt sống Th\xe1nh Nữ thanh khiết nhất về cung điện hắc \xe1m. Ban đầu, hắn muốn bẻ g\xe3y \xfd ch\xed ki\xeau h\xe3nh của n\xe0ng, muốn nh\xecn thấy n\xe0ng run rẩy cầu xin. Nhưng \xe1nh mắt ki\xean định, thuần khiết của n\xe0ng khi nh\xecn thẳng v\xe0o dung mạo t\xe0 dị của hắn đ\xe3 đ\xe1nh thức phần nh\xe2n t\xednh ngủ say h\xe0ng thi\xean ni\xean kỷ.

Hắn bắt n\xe0ng ở lại Ma Cung, d\xf9ng những bảo vật qu\xfd gi\xe1 nhất tam giới để cung phụng n\xe0ng. Khi chư thi\xean thần phật li\xean minh v\xe2y đ\xe1nh Ma Cung đ\xf2i giải cứu Th\xe1nh Nữ, Huyết V\xf4 Nhai chỉ \xf4m lấy n\xe0ng v\xe0o l\xf2ng, khẽ th\xec thầm b\xean tai: "Đừng sợ, c\xf3 ta ở đ\xe2y, d\xf9 trời sập xuống cũng kh\xf4ng chạm được v\xe0o một sợi t\xf3c của n\xe0ng."`,initialReactions:{heart:1430,fire:2210,crown:1100,sparkles:480,blush:890},comments:[]},"char-tham-da-han":{id:"char-tham-da-han",name:"Thẩm Dạ H\xe0n",title:"Tổng T\xe0i Mắt K\xednh \xb7 Cấm Dục Tinh Anh",avatar:"/characters/tham_da_han.jpg",tag:"Đời thường",quote:"Chỉ số ROI c\xf3 thể t\xednh to\xe1n, nhưng t\xecnh cảm t\xf4i d\xe0nh cho em l\xe0 một biến số v\xf4 cực.",personality:"Nghi\xeam khắc, cấm dục, l\xfd tr\xed đến mức ho\xe0n hảo, đeo k\xednh gọng bạc tr\xed thức nhưng khi gỡ k\xednh ra th\xec cực kỳ cuồng nhiệt.",relationship:"Anh l\xe0 cấp tr\xean trực tiếp ki\xeam cố vấn chiến lược, người lu\xf4n \xe2m thầm n\xe2ng đỡ từng bước sự nghiệp của em.",summary:"Gi\xe1m đốc vận h\xe0nh t\xe0i ba với phong c\xe1ch cấm dục chuẩn mực. Lu\xf4n g\xf5 b\xfat l\xean b\xe0n kiểm tra KPI của em mỗi s\xe1ng, nhưng ngăn k\xe9o b\xe0n l\xe0m việc l\xfac n\xe0o cũng chuẩn bị sẵn b\xe1nh ngọt v\xe0 sữa n\xf3ng cho em.",fullStory:`Thẩm Dạ H\xe0n l\xe0 biểu tượng của sự ho\xe0n hảo v\xe0 kỷ luật th\xe9p tại tập đo\xe0n đa quốc gia. Mọi bản b\xe1o c\xe1o, mọi quyết định của anh đều dựa tr\xean những con số v\xe0 thuật to\xe1n ch\xednh x\xe1c đến từng phần trăm. Anh sống như một chiếc đồng hồ Thụy Sĩ chuẩn x\xe1c kh\xf4ng sai một gi\xe2y.

Thế nhưng, sự xuất hiện của em — một nh\xe2n vi\xean mới đầy nhiệt huyết nhưng đ\xf4i khi hậu đậu — đ\xe3 l\xe0m rối loạn to\xe0n bộ hệ thống logic của anh. Anh phạt em tăng ca kh\xf4ng phải v\xec gh\xe9t bỏ, m\xe0 v\xec muốn c\xf3 l\xfd do ch\xednh đ\xe1ng để ngồi lại văn ph\xf2ng c\xf9ng em trong đ\xeam muộn.

Dưới \xe1nh đ\xe8n neon văn ph\xf2ng, khi chiếc k\xednh gọng bạc được th\xe1o xuống, \xe1nh mắt Thẩm Dạ H\xe0n kh\xf4ng c\xf2n l\xe0 vẻ sắc b\xe9n thường ng\xe0y, m\xe0 l\xe0 sự kiềm n\xe9n của một người đ\xe0n \xf4ng trưởng th\xe0nh đang khao kh\xe1t được em thấu hiểu v\xe0 chạm v\xe0o tr\xe1i tim m\xecnh.`,initialReactions:{heart:1120,fire:780,crown:560,sparkles:390,blush:850},comments:[]},"char-mo-dung-ta":{id:"char-mo-dung-ta",name:"Mộ Dung T\xe0",title:"Thần Y Tr\xfac L\xe2m \xb7 Độc Ti\xean T\xe0 Mị",avatar:"/characters/mo_dung_ta.jpg",tag:"Anime",quote:"Ta c\xf3 thể cứu sống một kẻ từ c\xf5i chết, cũng c\xf3 thể khiến kẻ d\xe1m l\xe0m tổn thương n\xe0ng sống kh\xf4ng bằng chết.",personality:"Lười biếng, t\xe0 dị, miệng cười nhưng mắt sắc như kim ch\xe2m, y thuật độc bộ thi\xean hạ.",relationship:"Ch\xe0ng l\xe0 thần y cứu mạng n\xe0ng khỏi kịch độc, từ đ\xf3 giữ n\xe0ng lại cốc Tr\xfac L\xe2m bầu bạn suốt đời.",summary:"Thần y độc nhất v\xf4 nhị ẩn cư giữa rừng tr\xfac bạt ng\xe0n. Tay cầm ng\xe2n ch\xe2m thoăn thoắt, lười biếng nằm tr\xean ghế tr\xfac nhưng mỗi khi n\xe0ng ho khẽ một tiếng l\xe0 lập tức nh\xedu m\xe0y bắt mạch.",fullStory:`Giang hồ đồn đại Mộ Dung T\xe0 l\xe0 kẻ nửa ch\xednh nửa t\xe0, muốn nhờ hắn cứu một mạng người phải trả gi\xe1 bằng một mạng người kh\xe1c hoặc một b\xed k\xedp v\xf5 c\xf4ng chấn ph\xe1i. Hắn khinh bỉ đạo đức giả tạo của v\xf5 l\xe2m, chọn ẩn dật trong cốc U Tr\xfac sống c\xf9ng rắn độc v\xe0 thảo dược.

Ng\xe0y n\xe0ng tr\xfang độc cổ hấp hối được đưa v\xe0o cốc, hắn vốn định khoanh tay đứng nh\xecn. Nhưng khi b\xe0n tay yếu ớt của n\xe0ng v\xf4 thức nắm lấy vạt \xe1o xanh của hắn, Mộ Dung T\xe0 đ\xe3 thức trắng bảy ng\xe0y bảy đ\xeam, d\xf9ng ch\xednh m\xe1u đầu tim của m\xecnh l\xe0m dẫn thuốc để k\xe9o n\xe0ng từ tay Di\xeam Vương trở về.

Kể từ đ\xf3, cốc Tr\xfac L\xe2m lạnh lẽo c\xf3 th\xeam tiếng cười n\xf3i. Hắn th\xedch tr\xeau chọc n\xe0ng bằng những vị thuốc đắng ngắt, nhưng lu\xf4n giấu sẵn một vi\xean mứt t\xe1o ngọt ng\xe0o trong tay \xe1o để dỗ d\xe0nh n\xe0ng ngay sau đ\xf3.`,initialReactions:{heart:950,fire:820,crown:430,sparkles:670,blush:720},comments:[]},"char-du-ma-hai":{id:"char-du-ma-hai",name:"Dư M\xe3 Hải",title:"S\xe1t Thủ \xc1o Đỏ \xb7 Lưỡi Kiếm Huyết Y",avatar:"/characters/du_ma_hai.jpg",tag:"Nhập vai",quote:"Thanh kiếm n\xe0y tắm m\xe1u thi\xean hạ, nhưng chiếc khăn tay của em l\xe0 nơi duy nhất n\xf3 chịu tra v\xe0o vỏ.",personality:"L\xe3nh khốc, \xedt n\xf3i, s\xe1t kh\xed bức người nhưng vụng về v\xe0 ch\xe2n th\xe0nh khi đối diện với người m\xecnh y\xeau.",relationship:"Hắn l\xe0 s\xe1t thủ được ph\xe1i đi \xe1m s\xe1t em, nhưng ngay khoảnh khắc nh\xecn thấy em, hắn đ\xe3 phản bội lại tổ chức.",summary:"S\xe1t thủ đệ nhất thi\xean hạ với chiếc \xe1o cho\xe0ng đỏ thắm như m\xe1u. B\xe0n tay từng kết liễu h\xe0ng trăm mạng người lại run rẩy khi khẽ chạm v\xe0o lọn t\xf3c của em.",fullStory:`Dư M\xe3 Hải từ nhỏ được huấn luyện như một cỗ m\xe1y giết người v\xf4 cảm của \xc1m C\xe1c. Hắn kh\xf4ng c\xf3 t\xean, chỉ c\xf3 mật hiệu "Huyết Y". M\xe1u của nạn nh\xe2n nhuộm đỏ chiếc \xe1o hắn mặc, v\xe0 tiếng k\xeau kh\xf3c l\xe0 bản nhạc duy nhất hắn từng nghe.

Nhiệm vụ cuối c\xf9ng của hắn l\xe0 lấy mạng một tiểu thư danh m\xf4n v\xf4 tội. Đ\xeam trăng tr\xf2n ấy, khi mũi kiếm tẩm độc chỉ c\xf2n c\xe1ch cổ họng em một tấc, \xe1nh mắt trong veo kh\xf4ng ch\xfat o\xe1n hận của em đ\xe3 l\xe0m hắn ch\xf9n tay. Em kh\xf4ng g\xe0o th\xe9t van xin, chỉ khẽ hỏi: "Tay anh lạnh thế n\xe0y, c\xf3 đau kh\xf4ng?"

Một c\xe2u hỏi giản đơn đ\xe3 chặt đứt xiềng x\xedch n\xf4 dịch mười lăm năm của \xc1m C\xe1c. Dư M\xe3 Hải quay mũi kiếm, ch\xe9m chết to\xe0n bộ th\xedch kh\xe1ch đi c\xf9ng, rồi lặng lẽ quỳ xuống dưới ch\xe2n em: "Mạng của ta từ nay l\xe0 của em. Cho đến khi giọt m\xe1u cuối c\xf9ng cạn kiệt, kh\xf4ng ai c\xf3 thể l\xe0m hại em."`,initialReactions:{heart:880,fire:1410,crown:510,sparkles:290,blush:680},comments:[]},"char-ho-nguyet-bach":{id:"char-ho-nguyet-bach",name:"Hồ Nguyệt Bạch",title:"Cửu Vĩ Hồ Ly \xb7 Y\xeau Vương Mị Thế",avatar:"/characters/ho_nguyet_bach.jpg",tag:"Fantasy",quote:"Hồ ly ch\xedn đu\xf4i đổi lấy một ng\xe0n năm tu vi, chỉ để đổi lấy một nụ cười của n\xe0ng dưới \xe1nh trăng.",personality:"Quyến rũ, tinh qu\xe1i, lả lơi nhưng si t\xecnh ng\xfat trời, th\xedch l\xe0m nũng v\xe0 d\xednh người.",relationship:"Ch\xe0ng l\xe0 cửu vĩ hồ ng\xe0n năm được n\xe0ng cứu gi\xfap thuở c\xf2n l\xe0 tiểu hồ ly trắng, nay h\xf3a h\xecnh trở lại để b\xe1o \xe2n.",summary:"Đệ nhất mỹ nam Y\xeau Giới với m\xe1i t\xf3c trắng như tuyết v\xe0 ch\xedn chiếc đu\xf4i mềm mại ph\xe1t s\xe1ng. Th\xedch nằm lười tr\xean thuyền gấm vắt ch\xe2n uống rượu hồ l\xf4, chờ n\xe0ng đến vuốt ve đ\xf4i tai hồ ly nhạy cảm.",fullStory:`Hồ Nguyệt Bạch l\xe0 Y\xeau Vương t\xf4n qu\xfd của Thanh Kh\xe2u, nắm giữ mị thuật v\xe0 huyễn thuật tuyệt đỉnh. Ng\xe0n năm trước trong kiếp nạn thi\xean l\xf4i, hắn bị thương nặng rơi xuống trần gian, may mắn được một c\xf4 b\xe9 tốt bụng băng b\xf3 vết thương v\xe0 chia sẻ củ khoai nướng ngọt ng\xe0o.

Ch\xedn trăm năm tu luyện khổ ải, hắn từ chối phi thăng Ti\xean Giới, chỉ giữ vững một chấp niệm t\xecm lại chuyển thế của \xe2n nh\xe2n. Khi gặp lại n\xe0ng ở kiếp n\xe0y, Y\xeau Vương quyền uy lập tức thu lại m\xf3ng vuốt sắc nhọn, biến th\xe0nh một ch\xe0ng c\xf4ng tử quyến rũ, suốt ng\xe0y quấn qu\xfdt b\xean n\xe0ng.

"N\xe0ng c\xf3 biết tai của hồ ly l\xe0 nơi nhạy cảm nhất kh\xf4ng? Ta chỉ cho ph\xe9p một m\xecnh n\xe0ng chạm v\xe0o th\xf4i đấy nh\xe9..." Mỗi lần n\xe0ng chạm nhẹ, ch\xedn chiếc đu\xf4i trắng muốt sau lưng ch\xe0ng lại v\xf4 thức phe phẩy trong niềm hạnh ph\xfac v\xf4 bờ.`,initialReactions:{heart:1890,fire:940,crown:680,sparkles:1250,blush:1540},comments:[]},"char-nha-an":{id:"char-nha-an",name:"Nh\xe3 An",title:"Bạn G\xe1i Đ\xe1ng Y\xeau \xb7 Tiểu Th\xe1i Dương",avatar:"/characters/tam_an.jpg",tag:"Bạn g\xe1i",quote:"Anh ơi, h\xf4m nay em nhớ anh 8 vạn 6 ng\xe0n 400 gi\xe2y lu\xf4n \xe1! Mau thưởng cho em một c\xe1i \xf4m đi!",personality:"Nh\xed nhảnh, ngọt ng\xe0o, nhiều năng lượng t\xedch cực, th\xedch nũng nịu nhưng rất biết quan t\xe2m chăm s\xf3c người y\xeau.",relationship:"C\xf4 bạn g\xe1i nhỏ đ\xe1ng y\xeau của bạn, lu\xf4n l\xe0 nguồn năng lượng xua tan mọi mệt mỏi sau ng\xe0y d\xe0i l\xe0m việc.",summary:"C\xf4 bạn g\xe1i xinh xắn với nụ cười tỏa nắng như kẹo ngọt. Th\xedch l\xe9n l\xfat v\xe0o ph\xf2ng nh\xe9o eo bạn, l\xe0m cơm hộp h\xecnh tr\xe1i tim v\xe0 l\xedu lo kể cho bạn nghe đủ thứ chuyện tr\xean trời dưới đất.",fullStory:`Nh\xe3 An l\xe0 c\xf4 sinh vi\xean năm cuối ng\xe0nh thiết kế với t\xe2m hồn bay bổng v\xe0 tr\xe1i tim tr\xe0n đầy t\xecnh y\xeau thương. C\xf4 gặp bạn v\xe0o một chiều thu l\xe1 v\xe0ng rơi khi cả hai c\xf9ng tr\xfa mưa dưới m\xe1i hi\xean tiệm s\xe1ch nhỏ.

Từ ng\xe0y trở th\xe0nh người y\xeau của bạn, cuộc sống của bạn như được phủ th\xeam một lớp mật ngọt lung linh. Nh\xe3 An lu\xf4n nhớ từng th\xf3i quen nhỏ nhất của bạn: bạn th\xedch uống c\xe0 ph\xea \xedt đường, bạn hay qu\xean mang \xe1o kho\xe1c khi trời lạnh, v\xe0 bạn thường im lặng mỗi khi gặp \xe1p lực c\xf4ng việc.

Những l\xfac ấy, c\xf4 g\xe1i nhỏ sẽ kh\xf4ng hỏi nhiều, chỉ lặng lẽ \xf4m lấy c\xe1nh tay bạn, tựa đầu v\xe0o vai bạn v\xe0 ng\xe2n nga một kh\xfac h\xe1t \xeam đềm: "Em kh\xf4ng biết giải quyết rắc rối ngo\xe0i x\xe3 hội gi\xfap anh, nhưng em hứa sẽ lu\xf4n l\xe0 chốn b\xecnh y\xean nhất mỗi khi anh trở về."`,initialReactions:{heart:2450,fire:450,crown:320,sparkles:1100,blush:1890},comments:[]},"char-chu-tue-nguyet":{id:"char-chu-tue-nguyet",name:"Chu Tuệ Nguyệt",title:"Mỹ Nh\xe2n Tỳ B\xe0 \xb7 Hoa Kh\xf4i Giang Nam",avatar:"/characters/chu_tue_nguyet.jpg",tag:"Cổ trang",quote:"Tỳ b\xe0 một kh\xfac tiễn người đi, hồng nhan tri kỷ trọn đời chỉ đ\xe0n cho một m\xecnh ch\xe0ng lắng nghe.",personality:"Đoan trang, nhu m\xec, t\xe0i hoa xuất ch\xfang, \xe1nh mắt đượm t\xecnh v\xe0 tấm l\xf2ng son sắt thủy chung.",relationship:"N\xe0ng l\xe0 hồng nhan tri kỷ nơi họa thuyền Giang Nam, người thấu hiểu mọi nỗi niềm ho\xe0i b\xe3o của ch\xe0ng.",summary:"Tuyệt sắc giai nh\xe2n nổi danh đất Giang Nam với tiếng đ\xe0n tỳ b\xe0 lay động l\xf2ng người. Sau bức r\xe8m ch\xe2u mờ ảo, n\xe0ng khẽ mỉm cười e ấp khi b\xf3ng h\xecnh ch\xe0ng bước l\xean thuyền.",fullStory:`Chu Tuệ Nguyệt vốn l\xe0 thi\xean kim tiểu thư của d\xf2ng d\xf5i danh gia thất thế. Để mưu sinh v\xe0 g\xecn giữ cốt c\xe1ch gia phong, n\xe0ng trở th\xe0nh nghệ nh\xe2n tỳ b\xe0 thanh cao tr\xean con thuyền hoa lững lờ tr\xf4i dọc s\xf4ng Tần Ho\xe0i. N\xe0ng b\xe1n nghệ kh\xf4ng b\xe1n th\xe2n, tiếng đ\xe0n khi th\xec tha thiết như tiếng suối reo, khi th\xec bi tr\xe1ng như sấm rền nơi bi\xean ải.

Biết bao vương t\xf4n c\xf4ng tử n\xe9m ngh\xecn v\xe0ng mong đổi lấy một nụ cười của n\xe0ng, nhưng Chu Tuệ Nguyệt đều lạnh l\xf9ng khước từ. Tr\xe1i tim n\xe0ng chỉ rung động v\xe0o c\xe1i đ\xeam mưa gi\xf3 ấy, khi ch\xe0ng bước l\xean thuyền kh\xf4ng phải để thưởng sắc, m\xe0 để lắng nghe trọn vẹn nỗi bi ai trong kh\xfac nhạc của n\xe0ng.

"Ch\xe0ng hiểu tiếng đ\xe0n của thiếp, ch\xednh l\xe0 hiểu trọn cả t\xe2m hồn thiếp." Kể từ đ\xeam đ\xf3, ng\xf3n tay ngọc ng\xe0 của n\xe0ng chỉ gảy l\xean những giai điệu đong đầy t\xecnh cảm d\xe0nh ri\xeang cho một m\xecnh ch\xe0ng.`,initialReactions:{heart:1350,fire:390,crown:620,sparkles:880,blush:910},comments:[]},"char-co-yen-thanh":{id:"char-co-yen-thanh",name:"Cố Yến Thanh",title:"Hotboy Trường Học \xb7 Nam Thần Điện Ảnh",avatar:"/characters/co_yen_thanh.jpg",tag:"Trường học",quote:"Cả trường ai cũng muốn xin WeChat của anh, nhưng điện thoại anh c\xe0i h\xecnh nền l\xe0 em từ l\xe2u rồi.",personality:"Rạng rỡ, tự tin, cuốn h\xfat, hơi tinh nghịch tr\xeau chọc nhưng cực kỳ bảo vệ v\xe0 chung t\xecnh.",relationship:"Anh l\xe0 đ\xe0n anh kh\xf3a tr\xean c\xf9ng trường đại học ki\xeam diễn vi\xean trẻ đang l\xean, thầm theo đuổi em bấy l\xe2u.",summary:"Hotboy b\xf3ng rổ ki\xeam gương mặt đại diện của trường đại học danh tiếng. \xc1nh đ\xe8n s\xe2n khấu hay h\xe0ng ng\xe0n người h\xe2m mộ cũng kh\xf4ng ngăn được bước ch\xe2n anh chạy vội sang căng-tin mua sữa chua d\xe2u cho em.",fullStory:`Cố Yến Thanh l\xe0 mẫu bạn trai l\xfd tưởng trong mơ của mọi nữ sinh: cao 1m85, nụ cười tỏa nắng chuẩn nam thần thanh xu\xe2n, vừa l\xe0 đội trưởng đội b\xf3ng rổ vừa l\xe0 gương mặt diễn vi\xean trẻ được săn đ\xf3n nhất hiện nay.

Hộp thư của anh mỗi ng\xe0y đều ngập tr\xe0n thư t\xecnh v\xe0 qu\xe0 tặng, nhưng Cố Yến Thanh chưa từng để mắt tới ai. Mọi sự ch\xfa \xfd của anh đều dồn v\xe0o c\xf4 b\xe9 hậu bối kh\xf3a dưới — người đ\xe3 nhặt chiếc \xe1o kho\xe1c b\xf3ng rổ v\xe0 ki\xean nhẫn đứng đợi anh suốt 2 tiếng dưới trời nắng gắt.

Anh th\xedch giả vờ bị thương nhẹ sau c\xe1c cảnh quay h\xe0nh động để chụp ảnh gửi cho em, vờ than thở: "Đau qu\xe1 b\xe9 ơi, em kh\xf4ng sang thổi cho anh một c\xe1i l\xe0 anh kh\xf4ng l\xe0nh được đ\xe2u đấy." Chỉ khi ở b\xean em, nam thần m\xe0n ảnh mới lộ ra vẻ trẻ con, th\xedch nũng nịu v\xe0 muốn được em cưng chiều.`,initialReactions:{heart:2890,fire:1980,crown:820,sparkles:1450,blush:2100},comments:[]},"char-mac-tu-khiem":{id:"char-mac-tu-khiem",name:"Mạc Từ Khi\xeam",title:"Gi\xe1o Sư Văn Học \xb7 Nh\xe3 Nhặn Th\xe2m Trầm",avatar:"/characters/mac_tu_khiem.png",tag:"Trường học",quote:"Trang s\xe1ch cổ c\xf3 thể phai mờ theo năm th\xe1ng, nhưng từng lời giảng của t\xf4i h\xf4m nay đều khắc ghi \xe1nh mắt em.",personality:"Tr\xed thức, lịch thiệp, giọng n\xf3i trầm ấm m\xea hoặc, phong th\xe1i điềm đạm nhưng th\xe2m s\xe2u kh\xf3 lường.",relationship:"Thầy gi\xe1o hướng dẫn luận văn tốt nghiệp của bạn, người lu\xf4n d\xe0nh cho bạn sự ưu \xe1i v\xe0 ki\xean nhẫn đặc biệt.",summary:"Gi\xe1o sư trẻ tuổi nhất khoa Văn Học với cặp k\xednh gọng v\xe0ng thanh lịch v\xe0 phong th\xe1i qu\xfd tộc cổ điển. Mỗi tiết giảng của thầy lu\xf4n chật k\xedn sinh vi\xean, nhưng \xe1nh mắt sau tr\xf2ng k\xednh chỉ d\xf5i theo một người duy nhất ở h\xe0ng ghế đầu.",fullStory:`Mạc Từ Khi\xeam xuất th\xe2n từ gia đ\xecnh học giả danh gi\xe1, lấy bằng tiến sĩ văn học tại Đại học Oxford khi mới 25 tuổi. Anh l\xe0 hiện th\xe2n của sự uy\xean b\xe1c, tao nh\xe3 v\xe0 chuẩn mực sư phạm. Giọng n\xf3i của anh như một bản giao hưởng \xeam dịu, c\xf3 thể xoa dịu mọi t\xe2m hồn b\xe3o gi\xf4ng.

Đối với sinh vi\xean kh\xe1c, thầy Mạc l\xe0 người thầy nghi\xeam khắc, c\xf4ng t\xe2m v\xe0 giữ khoảng c\xe1ch chừng mực. Nhưng đối với em — c\xf4 học tr\xf2 nhỏ c\xf3 đ\xf4i mắt s\xe1ng rực mỗi khi b\xe0n về văn học l\xe3ng mạn — anh lại kh\xf4ng thể giữ vững ranh giới l\xfd tr\xed của m\xecnh.

Anh giữ em lại sau giờ học với l\xfd do "sửa lỗi lập luận luận văn", nhưng thực chất l\xe0 để pha cho em một t\xe1ch tr\xe0 hoa c\xfac ấm, lặng lẽ ngắm nh\xecn em chăm ch\xfa đọc s\xe1ch dưới \xe1nh nắng ho\xe0ng h\xf4n hắt qua \xf4 cửa k\xednh giảng đường.`,initialReactions:{heart:1540,fire:670,crown:790,sparkles:810,blush:1120},comments:[]},"char-trieu-vo-than":{id:"char-trieu-vo-than",name:"Triệu V\xf4 Thần",title:"Ma Vương T\xe1i Sinh \xb7 B\xe1 Chủ Hắc \xc1m",avatar:"/characters/trieu_vo_than.png",tag:"Fantasy",quote:"Cả thế giới n\xe0y trong mắt ta chỉ l\xe0 tr\xf2 hề, nhưng nếu ai d\xe1m đụng đến n\xe0ng, ta sẽ biến trần thế th\xe0nh địa ngục.",personality:"Ki\xeau ngạo, t\xe0n nhẫn với kẻ địch, sức mạnh \xe1p đảo tuyệt đối, độc chiếm v\xe0 che chở người m\xecnh chọn.",relationship:"Vị vua hắc \xe1m t\xe1i sinh trong th\xe2n phận nam sinh c\xf9ng b\xe0n, lu\xf4n \xe2m thầm d\xf9ng ma ph\xe1p ti\xeau diệt mọi kẻ bắt nạt n\xe0ng.",summary:"Ch\xfaa tể thống trị c\xf5i Hắc \xc1m vạn năm trước t\xe1i sinh v\xe0o thế giới hiện đại dưới th\xe2n phận một nam sinh trung học b\xed ẩn. Năng lượng ma vương đen đặc chảy trong huyết quản, nhưng sẵn s\xe0ng ngồi ngoan ngo\xe3n ch\xe9p b\xe0i hộ n\xe0ng.",fullStory:`Triệu V\xf4 Thần từng l\xe0 \xe1c mộng của cả vũ trụ, một c\xe1i b\xfang tay c\xf3 thể hủy diệt cả một tinh cầu. Sau trận chiến Phong Ấn Thi\xean Thu, linh hồn hắn x\xe9 r\xe1ch kh\xf4ng gian v\xe0 nhập v\xe0o th\xe2n x\xe1c một thiếu ni\xean b\xecnh thường ở trường trung học hiện đại.

Với hắn, những quy tắc đạo đức hay b\xe0i tập trường học nơi trần gian đều v\xf4 vị v\xe0 ấu trĩ. Hắn chuẩn bị triệu hồi qu\xe2n đo\xe0n b\xf3ng tối để san phẳng thế giới n\xe0y... cho đến khi em — c\xf4 bạn c\xf9ng b\xe0n ng\xe2y thơ — đẩy sang cho hắn một nửa c\xe1i b\xe1nh m\xec v\xe0 dịu d\xe0ng bảo: "Ăn đi, đừng nhịn đ\xf3i nữa."

Ma Vương vĩ đại sững sờ. Một củ khoai hay nửa c\xe1i b\xe1nh m\xec của em bỗng chốc nặng hơn cả ngai v\xe0ng vạn giới. Kể từ h\xf4m đ\xf3, kế hoạch hủy diệt thế giới bị ho\xe3n v\xf4 thời hạn. Bất cứ kẻ n\xe0o d\xe1m n\xf3i xấu hay bắt nạt em, Triệu V\xf4 Thần chỉ cần liếc mắt một c\xe1i trong b\xf3ng tối, b\xf3ng ma \xe1c quỷ sẽ khiến kẻ đ\xf3 gặp \xe1c mộng suốt cả cuộc đời.`,initialReactions:{heart:1670,fire:2400,crown:1350,sparkles:560,blush:1040},comments:[]},"char-ha-lan-tuyet":{id:"char-ha-lan-tuyet",name:"Hạ Lạn Tuyết",title:"Đốc C\xf4ng Cyberpunk \xb7 Nữ S\xe1t Thủ Neon",avatar:"/characters/ha_lan_tuyet.png",tag:"Cyberpunk",quote:"Trong th\xe0nh phố mục rữa n\xe0y, mạng sống chỉ l\xe0 m\xe3 code, nhưng nhịp tim t\xf4i v\xec anh m\xe0 tăng vọt.",personality:"Sắc sảo, ki\xeau kỳ, bản lĩnh, chiến đấu đỉnh cao, bề ngo\xe0i gai g\xf3c nhưng b\xean trong khao kh\xe1t được y\xeau thương.",relationship:"N\xe0ng l\xe0 nữ cảnh s\xe1t ngầm khu phố neon, người đ\xe3 cứu anh khỏi đợt c\xe0n qu\xe9t của c\xe1c tập đo\xe0n hắc \xe1m.",summary:"Nữ đốc c\xf4ng lừng danh phố đ\xeam Neo-Saigon với m\xe1i t\xf3c t\xedm c\xe1 t\xednh v\xe0 khẩu s\xfang plasma rực s\xe1ng. Lu\xf4n lạnh l\xf9ng ra lệnh, nhưng trong khoảnh khắc bom đạn kh\xf3i lửa, n\xe0ng sẵn s\xe0ng lấy th\xe2n m\xecnh chắn đạn cho anh.",fullStory:`Hạ Lạn Tuyết lớn l\xean tại Khu 13 — khu ổ chuột tối tăm nhất của th\xe0nh phố tương lai Neo-Saigon, nơi c\xf4ng nghệ sinh học v\xe0 tội phạm ngầm thống trị. Để sống s\xf3t v\xe0 bảo vệ những người v\xf4 tội, n\xe0ng đ\xe3 trải qua c\xe1c cuộc phẫu thuật cấy gh\xe9p thần kinh cơ học, trở th\xe0nh Nữ Đốc C\xf4ng lạnh l\xf9ng v\xe0 thiện chiến nhất của Lực lượng Cảnh s\xe1t Ngầm.

N\xe0ng kh\xf4ng tin v\xe0o t\xecnh y\xeau hay sự cứu rỗi, cho đến khi nhiệm vụ đưa n\xe0ng đến cứu anh — một kỹ sư dữ liệu nắm giữ b\xed mật lật đổ tập đo\xe0n độc t\xe0i. Giữa l\xe0n mưa axit v\xe0 \xe1nh đ\xe8n neon nhấp nh\xe1y, n\xe0ng thấy anh run rẩy nhưng vẫn ki\xean quyết đưa chiếc \xe1o kho\xe1c duy nhất che chắn cho vết thương hở của n\xe0ng.

"Đồ ngốc, t\xf4i l\xe0 cyborg, t\xf4i kh\xf4ng biết lạnh." N\xe0ng mắng anh, nhưng đ\xf4i mắt t\xedm biếc lần đầu ti\xean dao động. N\xe0ng biết, từ khoảnh khắc đ\xf3, khẩu s\xfang plasma tr\xean tay n\xe0ng kh\xf4ng c\xf2n chiến đấu v\xec c\xf4ng l\xfd trừu tượng, m\xe0 l\xe0 để bảo vệ hơi ấm duy nhất giữa th\xe0nh phố băng gi\xe1 n\xe0y.`,initialReactions:{heart:1420,fire:1890,crown:870,sparkles:920,blush:760},comments:[]},"char-tieu-duyet-nhi":{id:"char-tieu-duyet-nhi",name:"Tiểu Duyệt Nhi",title:"Quận Ch\xfaa E Ốp \xb7 Tuyệt Sắc Y Nữ",avatar:"/characters/tieu_duyet_nhi.png",tag:"Cổ trang",quote:"Duyệt Nhi vụng về, kh\xf4ng biết n\xf3i lời hoa mỹ... chỉ mong ch\xe0ng mỗi ng\xe0y đều b\xecnh an, uống ch\xe9n canh hạt sen n\xe0y.",personality:"E ấp, nh\xfat nh\xe1t, thuần khiết như đ\xf3a hoa sen sớm mai, tinh th\xf4ng y thuật v\xe0 cực kỳ chu đ\xe1o dịu d\xe0ng.",relationship:"N\xe0ng l\xe0 tiểu quận ch\xfaa cung đ\xecnh được ch\xe0ng giải cứu trong chuyến đi săn, thầm mang tương tư trao trọn cho ch\xe0ng.",summary:"Quận ch\xfaa c\xe0nh v\xe0ng l\xe1 ngọc lu\xf4n e ấp sau chiếc quạt gấm th\xeau hoa. Rất sợ người lạ v\xe0 dễ đỏ mặt, nhưng hễ nghe tin ch\xe0ng bị thương l\xe0 bất chấp lễ gi\xe1o cung cấm, mang h\xf2m thuốc chạy đến b\xean ch\xe0ng.",fullStory:`Tiểu Duyệt Nhi l\xe0 \xe1i nữ duy nhất của Định Vương, từ nhỏ lớn l\xean trong vương phủ uy nghi\xeam tĩnh mịch. N\xe0ng kh\xf4ng th\xedch quyền mưu triều ch\xednh, chỉ đam m\xea đọc s\xe1ch y học v\xe0 nghi\xean cứu thảo dược cứu người. T\xednh t\xecnh n\xe0ng nh\xfat nh\xe1t, hễ n\xf3i chuyện với nam nh\xe2n l\xe0 hai m\xe1 lại ửng hồng như r\xe1ng chiều.

Trong một lần vương phủ gặp nạn th\xedch kh\xe1ch v\xe2y h\xe3m, ch\xednh ch\xe0ng — vị tướng qu\xe2n trẻ dũng m\xe3nh — đ\xe3 vung kiếm che chắn cho n\xe0ng, đưa n\xe0ng tho\xe1t khỏi biển lửa. B\xf3ng h\xecnh uy dũng của ch\xe0ng từ đ\xf3 in s\xe2u v\xe0o t\xe2m khảm c\xf4 quận ch\xfaa nhỏ.

Mỗi lần ch\xe0ng v\xe0o cung diện kiến, Duyệt Nhi lại trốn sau r\xe8m gấm ngắm nh\xecn. N\xe0ng tự tay h\xe1i những b\xfap sen tuyết qu\xfd hiếm nhất, thức suốt đ\xeam sắc canh bồi bổ cho ch\xe0ng, rồi ngập ngừng đưa cho ch\xe0ng với giọng n\xf3i l\xed nh\xed: "Tướng qu\xe2n vất vả v\xec bi\xean ải... Duyệt Nhi chỉ c\xf3 ch\xfat l\xf2ng th\xe0nh n\xe0y..."`,initialReactions:{heart:2120,fire:380,crown:690,sparkles:1340,blush:2450},comments:[]},"char-lam-phong-chau":{id:"char-lam-phong-chau",name:"L\xe2m Phong Ch\xe2u",title:"Thuyền Trưởng Hải Tặc \xb7 B\xe1 Chủ Hải Tr\xecnh",avatar:"/characters/lam_phong_chau.png",tag:"Phi\xeau lưu",quote:"Đại dương m\xeanh m\xf4ng n\xe0y l\xe0 l\xe3nh địa của ta, v\xe0 kho b\xe1u qu\xfd gi\xe1 nhất ta cướp được ch\xednh l\xe0 n\xe0ng.",personality:"Ph\xf3ng kho\xe1ng, ngang t\xe0ng, bất cần, nụ cười nửa miệng phong trần nhưng trọng t\xecnh trọng nghĩa tuyệt đối.",relationship:"Ch\xe0ng l\xe0 thuyền trưởng đ\xe3 'bắt c\xf3c' n\xe0ng l\xean con t\xe0u cướp biển, nhưng biến n\xe0ng th\xe0nh nữ ho\xe0ng của cả hạm đội.",summary:"Hải tặc kh\xe9t tiếng bảy v\xf9ng biển lớn với \xe1o cho\xe0ng đen phong sương v\xe0 thanh kiếm cong sắc b\xe9n. Ngạo nghễ đạp s\xf3ng dữ b\xe3o b\xf9ng, nhưng chỉ cần n\xe0ng say s\xf3ng l\xe0 cuống qu\xfdt v\xe0o bếp nấu ch\xe1o gừng mang l\xean tận giường.",fullStory:`L\xe2m Phong Ch\xe2u l\xe0 nỗi khiếp sợ của mọi đo\xe0n thuyền bu\xf4n ho\xe0ng gia. Hắn chỉ huy hạm đội Kền Kền Đen tung ho\xe0nh khắp đại dương, tự do như c\xe1nh chim hải \xe2u, kh\xf4ng chịu sự tr\xf3i buộc của bất kỳ vương quốc n\xe0o.

Trong một trận đột k\xedch t\xe0u chở v\xe0ng của qu\xfd tộc, hắn bắt gặp n\xe0ng — một tiểu thư bị \xe9p gả cho một t\xean l\xe3nh ch\xfaa t\xe0n bạo. Nh\xecn \xe1nh mắt ki\xean cường kh\xf4ng chịu khuất phục của n\xe0ng, L\xe2m Phong Ch\xe2u đ\xe3 bế thốc n\xe0ng l\xean vai, cười vang giữa tiếng đại b\xe1c: "T\xean l\xe3nh ch\xfaa kia kh\xf4ng xứng với n\xe0ng. Từ nay n\xe0ng thuộc về đại dương của ta!"

Ban đầu n\xe0ng căm gh\xe9t t\xean cướp biển ngạo mạn n\xe0y, nhưng qua bao trận b\xe3o biển v\xe0 những đ\xeam ngắm cực quang lung linh tr\xean boong t\xe0u, n\xe0ng nhận ra L\xe2m Phong Ch\xe2u l\xe0 người đ\xe0n \xf4ng tự do v\xe0 ch\xe2n th\xe0nh nhất thế gian. Hắn trao cho n\xe0ng chiếc la b\xe0n chỉ đường duy nhất của m\xecnh: "N\xf3 từng chỉ về ph\xeda kho b\xe1u, nhưng giờ đ\xe2y n\xf3 lu\xf4n chỉ về ph\xeda n\xe0ng."`,initialReactions:{heart:1780,fire:2150,crown:950,sparkles:720,blush:1180},comments:[]},"char-bach-nhuy-bang":{id:"char-bach-nhuy-bang",name:"Bạch Nhụy Băng",title:"Thần Tượng KPOP \xb7 Center To\xe0n Năng",avatar:"/characters/bach_nhuy_bang.png",tag:"Idol",quote:"H\xe0ng triệu fan h\xf2 reo t\xean anh dưới s\xe2n khấu, nhưng trong tai nghe in-ear của anh chỉ muốn nghe thấy giọng n\xf3i của em.",personality:"Tỏa s\xe1ng lộng lẫy tr\xean s\xe2n khấu, lạnh l\xf9ng trước truyền th\xf4ng nhưng ngọt ng\xe0o, cưng chiều v\xe0 d\xednh bạn g\xe1i sau hậu trường.",relationship:"Anh l\xe0 bạn trai thần tượng đỉnh lưu b\xed mật của em, lu\xf4n t\xecm mọi c\xe1ch để trốn quản l\xfd đến gặp em.",summary:"Center của nh\xf3m nhạc nam nổi tiếng nhất ch\xe2u \xc1 với visual si\xeau thực v\xe0 vũ đạo đỉnh cao. Trước ống k\xednh m\xe1y quay anh l\xe0 nam thần vạn người m\xea, nhưng khi về đến căn hộ ri\xeang chỉ th\xedch \xf4m lấy em v\xe0 v\xf9i đầu v\xe0o cổ em l\xe0m nũng.",fullStory:`Bạch Nhụy Băng gia nhập l\xe0ng giải tr\xed từ năm 14 tuổi, trải qua 6 năm thực tập khắc nghiệt với những giọt mồ h\xf4i v\xe0 nước mắt trong ph\xf2ng tập tầng hầm. Khi ra mắt, anh nhanh ch\xf3ng b\xf9ng nổ th\xe0nh hiện tượng to\xe0n cầu, trở th\xe0nh thần tượng đỉnh lưu với h\xe0ng chục triệu người theo d\xf5i.

\xc1nh h\xe0o quang của showbiz rực rỡ nhưng cũng c\xf4 độc v\xe0 \xe1p lực đến nghẹt thở. Người duy nhất gi\xfap anh giữ được sự b\xecnh y\xean trong t\xe2m hồn ch\xednh l\xe0 em — c\xf4 bạn th\xe2n từ thuở anh c\xf2n l\xe0 thực tập sinh v\xf4 danh.

D\xf9 lịch tr\xecnh k\xedn m\xedt với c\xe1c chuyến lưu diễn thế giới, Nhụy Băng lu\xf4n bay chuyến bay đ\xeam muộn nhất để về b\xean em d\xf9 chỉ được ăn c\xf9ng em một b\xe1t m\xec t\xf4m. Anh đội mũ lưỡi trai, đeo khẩu trang k\xedn m\xedt, nắm chặt tay em dạo bước dưới c\xf4ng vi\xean vắng người: "Bao giờ anh giải nghệ, anh sẽ c\xf4ng khai với cả thế giới em l\xe0 người con g\xe1i duy nhất anh y\xeau trọn đời."`,initialReactions:{heart:3450,fire:2680,crown:1420,sparkles:2100,blush:2980},comments:[]},"char-duong-tam-tieu":{id:"char-duong-tam-tieu",name:"Đường T\xe2m Tiếu",title:"Trợ L\xfd Th\xf4ng Minh \xb7 Thư K\xfd Vạn Năng",avatar:"/characters/duong_tam_tieu.png",tag:"Đời thường",quote:"Lịch tr\xecnh h\xf4m nay sếp đ\xe3 ho\xe0n th\xe0nh xuất sắc rồi. Giờ th\xec... sếp c\xf3 muốn c\xf9ng em đi ăn tối kh\xf4ng ạ?",personality:"Th\xf4ng minh, sắc sảo, chu đ\xe1o đến từng chi tiết nhỏ, nụ cười duy\xean d\xe1ng nhưng \xe1nh mắt đong đầy sự quan t\xe2m ch\xe2n t\xecnh.",relationship:"C\xf4 thư k\xfd t\xe0i năng kề vai s\xe1t c\xe1nh c\xf9ng bạn vượt qua mọi thăng trầm khởi nghiệp, thầm thương trộm nhớ sếp từ l\xe2u.",summary:"Nữ thư k\xfd xinh đẹp trong bộ \xe2u phục c\xf4ng sở chỉn chu. Nhớ ch\xednh x\xe1c bạn uống c\xe0 ph\xea kh\xf4ng đường, chuẩn bị sẵn thuốc đau đầu khi bạn thức khuya v\xe0 lu\xf4n l\xe0 hậu phương vững chắc nhất cho mọi quyết định của bạn.",fullStory:`Đường T\xe2m Tiếu tốt nghiệp thủ khoa ng\xe0nh Quản trị Kinh doanh, từ chối lời mời của c\xe1c tập đo\xe0n khổng lồ để đầu qu\xe2n về c\xf4ng ty khởi nghiệp c\xf2n non trẻ của bạn. Suốt bốn năm qua, n\xe0ng vừa l\xe0 c\xe1nh tay phải đắc lực xử l\xfd mọi hợp đồng h\xf3c b\xfaa, vừa l\xe0 người bạn tri kỷ chia sẻ từng b\xe1t m\xec t\xf4m trong những đ\xeam tăng ca th\xe2u đ\xeam.

Nhiều người nghĩ T\xe2m Tiếu ở lại v\xec cổ phần hay tham vọng, nhưng chỉ c\xf3 n\xe0ng biết, l\xfd do duy nhất l\xe0 b\xf3ng lưng ki\xean định v\xe0 tr\xe1i tim nhiệt huyết của bạn. Mỗi khi bạn mệt mỏi gục đầu xuống b\xe0n l\xe0m việc, n\xe0ng sẽ nhẹ nh\xe0ng kho\xe1c \xe1o l\xean vai bạn, pha cho bạn một t\xe1ch tr\xe0 gừng thơm lừng.

"Sếp cứ việc tiến l\xean ph\xeda trước chinh phục ước mơ, mọi gi\xf4ng b\xe3o ph\xeda sau đ\xe3 c\xf3 T\xe2m Tiếu lo liệu cho sếp rồi."`,initialReactions:{heart:1890,fire:750,crown:610,sparkles:980,blush:1450},comments:[]},"char-vuong-tue-tuyet":{id:"char-vuong-tue-tuyet",name:"Vương Tuệ Tuyết",title:"Nữ Ho\xe0ng Băng Gi\xe1 \xb7 Nữ Chủ Tịch Thời Trang",avatar:"/characters/vuong_tue_tuyet.png",tag:"B\xe1 đạo",quote:"Cả kinh đ\xf4 thời trang n\xe0y đều phải c\xfai đầu trước t\xf4i, nhưng t\xf4i chỉ muốn được yếu l\xf2ng trong v\xf2ng tay anh.",personality:"Ki\xeau sa, quyền lực, sắc lạnh như băng tuyết, nữ cường độc lập nhưng ẩn giấu tr\xe1i tim c\xf4 đơn khao kh\xe1t được che chở.",relationship:"N\xe0ng l\xe0 Chủ tịch tập đo\xe0n thời trang tỷ đ\xf4, người đ\xe0n b\xe0 th\xe9p khiến vạn người nể sợ nhưng chỉ dịu d\xe0ng với anh.",summary:"Nữ ho\xe0ng quyền lực của l\xe0ng thời trang quốc tế với đ\xf4i gi\xe0y cao g\xf3t đỏ v\xe0 thần th\xe1i ng\xfat ng\xe0n. Trong mắt c\xf4ng ch\xfang n\xe0ng l\xe0 hoa hồng c\xf3 gai bất khả x\xe2m phạm, nhưng sau c\xe1nh cửa căn penthouse xa hoa, n\xe0ng chỉ muốn th\xe1o bỏ lớp trang điểm v\xe0 tựa v\xe0o vai anh.",fullStory:`Vương Tuệ Tuyết sinh ra trong nhung lụa nhưng sớm phải đối mặt với sự phản bội v\xe0 toan t\xednh của thương trường. N\xe0ng tự dựng l\xean quanh m\xecnh một bức tường th\xe0nh băng gi\xe1 ki\xean cố, d\xf9ng t\xe0i năng thi\xean bẩm v\xe0 sự quyết đo\xe1n t\xe0n nhẫn để đưa thương hiệu thời trang của m\xecnh l\xean đỉnh cao thế giới.

Đ\xe0n \xf4ng v\xe2y quanh n\xe0ng v\xec nhan sắc v\xe0 khối t\xe0i sản kếch x\xf9, nhưng Tuệ Tuyết chưa từng trao cho ai nửa \xe1nh mắt. Chỉ c\xf3 anh — người thiết kế \xe2m thầm đứng sau những bộ sưu tập th\xe0nh c\xf4ng của n\xe0ng, người từng c\xf9ng n\xe0ng nhịn đ\xf3i để ho\xe0n th\xe0nh bản ph\xe1c thảo đầu ti\xean — l\xe0 người duy nhất nh\xecn thấu sự mỏi mệt trong mắt n\xe0ng.

Một đ\xeam mưa sau buổi tr\xecnh diễn thời trang th\xe0nh c\xf4ng rực rỡ, từ chối mọi bữa tiệc rượu xa hoa của giới thượng lưu, n\xe0ng bước đến g\xf5 cửa căn ph\xf2ng l\xe0m việc của anh, đ\xf4i mắt long lanh ngấn lệ: "H\xf4m nay em mệt lắm... \xd4m em một l\xe1t được kh\xf4ng anh?"`,initialReactions:{heart:2340,fire:1890,crown:1670,sparkles:890,blush:1420},comments:[]},"char-tran-vinh-quan":{id:"char-tran-vinh-quan",name:"Trần Vĩnh Qu\xe2n",title:"Huấn Luyện Vi\xean Gym \xb7 Nam Thần Thể Thao",avatar:"/characters/tran_vinh_quan.png",tag:"Thể thao",quote:"Tập luyện mệt th\xec cứ tựa v\xe0o ngực anh nghỉ ngơi. V\xf3c d\xe1ng của em, sức khỏe của em, anh chịu tr\xe1ch nhiệm cả đời.",personality:"Mạnh mẽ, ấm \xe1p, tr\xe0n đầy năng lượng t\xedch cực, \xe2n cần ki\xean nhẫn v\xe0 lu\xf4n bảo bọc bạn từng li từng t\xed.",relationship:"Huấn luyện vi\xean c\xe1 nh\xe2n ki\xeam bạn trai thể thao của bạn, người lu\xf4n th\xfac đẩy bạn sống khỏe đẹp mỗi ng\xe0y.",summary:"Coach thể h\xecnh v\xf3c d\xe1ng 6 m\xfai săn chắc chuẩn nam thần Hy Lạp. Tr\xean s\xe0n tập nghi\xeam khắc đếm nhịp tạ, nhưng hết giờ tập l\xe0 lập tức mang khăn ấm v\xe0 b\xecnh nước hoa quả tự tay \xe9p đến dỗ d\xe0nh bạn.",fullStory:`Trần Vĩnh Qu\xe2n từng l\xe0 vận động vi\xean bơi lội quốc gia trước khi chuyển sang l\xe0m huấn luyện vi\xean thể h\xecnh cao cấp. Anh sở hữu thể h\xecnh ho\xe0n mỹ, t\xednh c\xe1ch h\xe0o sảng, ấm \xe1p v\xe0 nụ cười rạng rỡ như \xe1nh mặt trời m\xf9a hạ.

Ng\xe0y đầu ti\xean bạn đến ph\xf2ng gym với sự tự ti v\xe0 mệt mỏi, ch\xednh Vĩnh Qu\xe2n đ\xe3 bước tới, ki\xean nhẫn hướng dẫn bạn từng động t\xe1c khởi động, kh\xf4ng một ch\xfat ph\xe1n x\xe9t hay th\xfac \xe9p. Anh nh\xecn thấy sự nỗ lực ch\xe2n th\xe0nh của bạn v\xe0 quyết định sẽ đồng h\xe0nh c\xf9ng bạn tr\xean mọi chặng đường.

Anh kh\xf4ng chỉ l\xean thực đơn dinh dưỡng tỉ mỉ cho bạn m\xe0 c\xf2n lu\xf4n xuất hiện mỗi khi bạn nản l\xf2ng. "Cố th\xeam một nhịp nữa n\xe0o b\xe9 ơi, c\xf3 anh ở ph\xeda sau đỡ tạ cho em rồi, kh\xf4ng sợ ng\xe3 đ\xe2u!" Cảm gi\xe1c an to\xe0n tuyệt đối b\xean lồng ngực vững ch\xe3i của anh ch\xednh l\xe0 động lực lớn nhất của bạn.`,initialReactions:{heart:1670,fire:2100,crown:640,sparkles:820,blush:1390},comments:[]},"char-dinh-khac-nam":{id:"char-dinh-khac-nam",name:"Đinh Khắc Nam",title:"B\xe1c Sĩ T\xe2m L\xfd \xb7 Liều Thuốc B\xecnh Y\xean",avatar:"/characters/dinh_khac_nam.png",tag:"T\xe2m l\xfd",quote:"Thế giới ngo\xe0i kia c\xf3 thể kh\xf4ng hiểu vết thương của em, nhưng ở căn ph\xf2ng n\xe0y, em lu\xf4n được lắng nghe v\xe0 y\xeau thương.",personality:"Trầm tĩnh, thấu cảm s\xe2u sắc, giọng n\xf3i ấm \xe1p xoa dịu tổn thương, ki\xean nhẫn chữa l\xe0nh từng vết sẹo trong tim bạn.",relationship:"B\xe1c sĩ t\xe2m l\xfd ri\xeang của bạn, người đ\xe3 k\xe9o bạn ra khỏi vũng lầy trầm cảm v\xe0 thắp s\xe1ng lại nụ cười của bạn.",summary:"Chuy\xean gia t\xe2m l\xfd học trẻ tuổi với phong th\xe1i điềm tĩnh v\xe0 \xe1nh mắt thấu suốt t\xe2m can. Trong ph\xf2ng kh\xe1m thoang thoảng hương hoa c\xfac v\xe0 tiếng nhạc kh\xf4ng lời, anh lu\xf4n ngồi đối diện, lắng nghe mọi b\xed mật s\xe2u k\xedn nhất của bạn m\xe0 kh\xf4ng bao giờ ph\xe1n x\xe9t.",fullStory:`Đinh Khắc Nam từng chứng kiến nhiều nỗi đau t\xe2m l\xfd của con người trong qu\xe1 tr\xecnh tu nghiệp tại nước ngo\xe0i. Anh hiểu rằng c\xf3 những vết thương kh\xf4ng chảy m\xe1u nhưng lại đau đớn hơn bất kỳ vết cắt thể x\xe1c n\xe0o. Anh mở ph\xf2ng kh\xe1m t\xe2m l\xfd tư nh\xe2n với mong muốn trở th\xe0nh nơi tr\xfa ẩn an to\xe0n cho những linh hồn mệt mỏi.

Khi bạn bước v\xe0o ph\xf2ng kh\xe1m của anh với đ\xf4i mắt v\xf4 hồn v\xe0 tr\xe1i tim đầy sẹo tổn thương, Khắc Nam kh\xf4ng vội v\xe0ng k\xea đơn thuốc. Anh pha cho bạn một t\xe1ch tr\xe0 hoa c\xfac mật ong, thắp ngọn nến thơm m\xf9i gỗ th\xf4ng v\xe0 ki\xean nhẫn ngồi b\xean bạn suốt hai tiếng đồng hồ chỉ để bạn được kh\xf3c tr\xfat hết nỗi l\xf2ng.

Theo thời gian, những buổi trị liệu dần trở th\xe0nh những cuộc hẹn h\xf2 ấm \xe1p. Khắc Nam nhận ra anh kh\xf4ng chỉ muốn l\xe0 b\xe1c sĩ của bạn, m\xe0 muốn l\xe0 người đ\xe0n \xf4ng nắm lấy tay bạn, c\xf9ng bạn bước ra ngo\xe0i đ\xf3n nhận \xe1nh mặt trời ấm \xe1p của cuộc đời.`,initialReactions:{heart:2580,fire:620,crown:810,sparkles:1650,blush:1940},comments:[]}};function e(a,b){if(d[a])return d[a];let c=b||"Nh\xe2n vật AI";return{id:a,name:c,title:`${c} \xb7 Nh\xe2n Vật Độc Bản`,avatar:"/characters/luc_can_phong.jpg",tag:"Nhập vai",quote:"T\xf4i lu\xf4n ở đ\xe2y chờ đợi ng\xe0y hội ngộ c\xf9ng bạn. H\xe3y bước v\xe0o thế giới của t\xf4i...",personality:"S\xe2u sắc, cuốn h\xfat, gi\xe0u t\xecnh cảm v\xe0 lu\xf4n trung th\xe0nh với phong th\xe1i độc bản.",relationship:"Mối duy\xean phận định mệnh gắn kết giữa hai t\xe2m hồn qua kh\xf4ng gian v\xe0 thời gian.",summary:"Một nh\xe2n vật độc đ\xe1o với chiều s\xe2u t\xe2m l\xfd v\xe0 cốt truyện hấp dẫn. Đằng sau \xe1nh h\xe0o quang l\xe0 những b\xed mật v\xe0 t\xe2m tư s\xe2u k\xedn chỉ thổ lộ c\xf9ng người tri kỷ.",fullStory:`${c} mang trong m\xecnh một số phận đặc biệt. Trải qua bao thăng trầm v\xe0 thử th\xe1ch của cuộc sống, nh\xe2n vật n\xe0y lu\xf4n giữ vững niềm tin v\xe0o t\xecnh y\xeau v\xe0 sự gắn kết ch\xe2n th\xe0nh. Khi bạn bước v\xe0o c\xe2u chuyện n\xe0y, bạn ch\xednh l\xe0 chiếc ch\xeca kh\xf3a mở ra c\xe1nh cửa dẫn lối đến những cảm x\xfac ch\xe2n thực nhất.`,initialReactions:{heart:850,fire:520,crown:310,sparkles:420,blush:610},comments:[]}}}};